// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.csf;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.Arrays;
import java.util.Random;

import org.eclipse.rdf4j.sail.lmdb.csf.CsfRowLookupAccelerators.Index;
import org.eclipse.rdf4j.sail.lmdb.csf.CsfRowLookupAccelerators.Kind;
import org.eclipse.rdf4j.sail.lmdb.csf.CsfRowLookupAccelerators.LearnedIndex;
import org.eclipse.rdf4j.sail.lmdb.csf.CsfRowLookupAccelerators.MinimalPerfectHashIndex;
import org.junit.jupiter.api.Test;

class CsfRowLookupAcceleratorsTest {

	@Test
	void everyAcceleratorMatchesUnsignedBinarySearch() {
		Random random = new Random(0x4353_4652_4f57_4cL);
		for (int size : new int[] { 0, 1, 2, 7, 16, 63, 128, 257, 512, 1_024 }) {
			for (int round = 0; round < 12; round++) {
				long[] rows = randomRows(random, size);
				for (Index index : indexes(rows)) {
					for (int ordinal = 0; ordinal < size; ordinal++) {
						assertEquals(ordinal, index.find(rows[ordinal]), index.kind().name());
					}
					for (int miss = 0; miss < 2_048; miss++) {
						long target = random.nextLong();
						int expected = CsfRowLookupAccelerators.binarySearchUnsigned(rows, 0, size - 1, target);
						assertEquals(expected, index.find(target), index.kind().name());
					}
				}
			}
		}
	}

	@Test
	void handlesUnsignedRangeAcrossSignedBoundary() {
		long[] rows = {
				Long.MAX_VALUE - 2,
				Long.MAX_VALUE,
				Long.MIN_VALUE,
				Long.MIN_VALUE + 2,
				-2L,
				-1L
		};
		for (Index index : indexes(rows)) {
			for (int ordinal = 0; ordinal < rows.length; ordinal++) {
				assertEquals(ordinal, index.find(rows[ordinal]), index.kind().name());
			}
			assertEquals(-1, index.find(0));
			assertEquals(-1, index.find(Long.MIN_VALUE + 1));
			assertEquals(-1, index.find(-3L));
		}
	}

	@Test
	void learnedBoundIsExactForUniformRowsAndDegradesSafelyForSkew() {
		long[] uniform = new long[1_024];
		for (int i = 0; i < uniform.length; i++) {
			uniform[i] = 0xa000_0000_0000_0000L + i * 17L;
		}
		LearnedIndex exact = CsfRowLookupAccelerators.learned(uniform, uniform.length);
		assertEquals(0, exact.maxError());
		assertEquals(1, exact.worstCaseCandidates());

		long[] skewed = new long[1_024];
		for (int i = 0; i < skewed.length; i++) {
			skewed[i] = i < 1_000 ? i : 1_000_000_000L + i;
		}
		LearnedIndex model = CsfRowLookupAccelerators.learned(skewed, skewed.length);
		assertTrue(model.maxError() > 400);
		for (int i = 0; i < skewed.length; i++) {
			assertEquals(i, model.find(skewed[i]));
		}
	}

	@Test
	void rawHighBitsDegenerateOnTaggedIdsWhileRangeRelativeRadixRemainsSelective() {
		long[] rows = new long[1_024];
		for (int i = 0; i < rows.length; i++) {
			rows[i] = 0x7a12_3400_0000_0000L + i * 1_000_003L;
		}
		Index high = CsfRowLookupAccelerators.highBits(rows, rows.length, 8);
		Index local = CsfRowLookupAccelerators.pageRadix(rows, rows.length, 6);
		assertEquals(rows.length, high.worstCaseCandidates());
		assertTrue(local.worstCaseCandidates() <= 32, "radix max=" + local.worstCaseCandidates());
	}

	@Test
	void minimalPerfectHashUsesOneSlotPerRowAndVerifiesMisses() {
		long[] rows = randomRows(new Random(7), 1_024);
		MinimalPerfectHashIndex index = CsfRowLookupAccelerators.minimalPerfectHash(rows, rows.length);
		assertEquals(1, index.worstCaseCandidates());
		assertTrue(index.auxiliaryBytes() >= (long) rows.length * Character.BYTES);
		assertTrue(index.buildAttempts() >= 1 && index.buildAttempts() <= 64);
		for (int i = 0; i < rows.length; i++) {
			assertEquals(i, index.find(rows[i]));
		}
		for (long target = 0; target < 10_000; target++) {
			if (CsfRowLookupAccelerators.binarySearchUnsigned(rows, 0, rows.length - 1, target) < 0) {
				assertEquals(-1, index.find(target));
			}
		}
	}

	@Test
	void adaptiveNeverSelectsMemoryHeavyHashStructures() {
		long[] uniform = new long[1_024];
		for (int i = 0; i < uniform.length; i++) {
			uniform[i] = 10_000L + i * 9L;
		}
		assertEquals(Kind.LEARNED, CsfRowLookupAccelerators.adaptive(uniform, uniform.length).kind());

		long[] skewed = new long[1_024];
		for (int i = 0; i < skewed.length; i++) {
			skewed[i] = i < 900 ? i : (1L << 40) | i;
		}
		Kind selected = CsfRowLookupAccelerators.adaptive(skewed, skewed.length).kind();
		assertNotEquals(Kind.MINIMAL_PERFECT_HASH, selected);
		assertNotEquals(Kind.HASH_PARTITIONED, selected);
	}

	@Test
	void rejectsUnsortedAndDuplicateRows() {
		for (Kind kind : Kind.values()) {
			assertThrows(IllegalArgumentException.class,
					() -> CsfRowLookupAccelerators.build(kind, new long[] { 2, 1 }, 2), kind.name());
			assertThrows(IllegalArgumentException.class,
					() -> CsfRowLookupAccelerators.build(kind, new long[] { 1, 1 }, 2), kind.name());
		}
	}

	private static Index[] indexes(long[] rows) {
		return new Index[] {
				CsfRowLookupAccelerators.binary(rows, rows.length),
				CsfRowLookupAccelerators.pageRadix(rows, rows.length, 6),
				CsfRowLookupAccelerators.highBits(rows, rows.length, 8),
				CsfRowLookupAccelerators.learned(rows, rows.length),
				CsfRowLookupAccelerators.minimalPerfectHash(rows, rows.length),
				CsfRowLookupAccelerators.hashPartitioned(rows, rows.length, 4),
				CsfRowLookupAccelerators.adaptive(rows, rows.length)
		};
	}

	private static long[] randomRows(Random random, int size) {
		long[] rows = new long[size];
		for (int i = 0; i < size; i++) {
			long candidate;
			do {
				candidate = random.nextLong();
			} while (contains(rows, i, candidate));
			rows[i] = candidate;
		}
		for (int i = 0; i < rows.length; i++) {
			rows[i] ^= Long.MIN_VALUE;
		}
		Arrays.sort(rows);
		for (int i = 0; i < rows.length; i++) {
			rows[i] ^= Long.MIN_VALUE;
		}
		return rows;
	}

	private static boolean contains(long[] rows, int length, long target) {
		for (int i = 0; i < length; i++) {
			if (rows[i] == target) {
				return true;
			}
		}
		return false;
	}
}
